  return (
    <main className="mx-auto max-w-4xl px-6 py-12">
      <h1 className="text-3xl font-semibold">Deals</h1>
      <Suspense fallback={<p className="mt-6 text-stone-600">Loading deals…</p>}>
        <DealList />
      </Suspense>
    </main>
  );
}

async function DealList() {
  const deals = await getDeals();

  return (
    <ul className="mt-6 space-y-2">
      {deals.map((deal) => (
        <li key={deal.id}>
          {deal.title}: <Price cents={deal.salePriceCents} />
        </li>
      ))}
    </ul>
  );
}

